// The compiler has to resolve a relative import, check types, and emit both products. Written so that a compiler which emits
// without checking would still satisfy the file assertion, but a compiler that refuses to run at all would not.
import { double } from "./math.js";

export interface Answer {
  readonly value: number;
  readonly label: string;
}

export const answer: Answer = { value: double(21), label: "the answer" };

